from pyspark.sql import functions as F


def hba1c_band(observations):
    value = F.col("value")
    band = (
        F.when(F.isnan(value), None)
        .when(value < 5.7, "normal")
        .when(value < 6.5, "prediabetes")
        .when(value >= 6.5, "diabetes")
    )
    return observations.filter(F.col("code") == "HBA1C").select("observation_id", "value", band.alias("band"))


def clean(observations):
    return observations.fillna(0.0, subset=["value"])


def test_clean():
    test_input = spark.createDataFrame([("O1", 5.6), ("O2", None)], "observation_id STRING, value DOUBLE")
    assert clean(test_input).filter(F.col("value").isNull()).count() == 0
    print("test_clean passed")


def test_pipeline():
    test_input = spark.createDataFrame(
        [
            ("OBS1", "ENC1", "PAT1", "HBA1C", "Hemoglobin A1c", 7.1, "%", None),
            ("OBS2", "ENC1", "PAT1", "HBA1C", "Hemoglobin A1c", None, "%", None),
        ],
        observations.schema,
    )
    got = sorted((r["observation_id"], r["band"]) for r in hba1c_band(clean(test_input)).collect())
    assert got == [("OBS1", "diabetes")], f"got {got}"


test_clean()
test_pipeline()
